500	 *
501	 * It returns 0 if plain look up failed (blocks have not been allocated), in
502	 * that case, buffer head is unmapped
503	 *
504	 * It returns the error in case of allocation failure.
505	 */
506	int ext4_map_blocks(handle_t *handle, struct inode *inode,
507			    struct ext4_map_blocks *map, int flags)
508	{
509		struct extent_status es;
510		int retval;
511	#ifdef ES_AGGRESSIVE_TEST
512		struct ext4_map_blocks orig_map;
513	
514		memcpy(&orig_map, map, sizeof(*map));
515	#endif
516	
517		map->m_flags = 0;
518		ext_debug("ext4_map_blocks(): inode %lu, flag %d, max_blocks %u,"
519			  "logical block %lu\n", inode->i_ino, flags, map->m_len,
520			  (unsigned long) map->m_lblk);
521	
522		/* We can handle the block number less than EXT_MAX_BLOCKS */
523		if (unlikely(map->m_lblk >= EXT_MAX_BLOCKS))
524			return -EIO;
525	
526		/* Lookup extent status tree firstly */
527		if (ext4_es_lookup_extent(inode, map->m_lblk, &es)) {
528			ext4_es_lru_add(inode);
529			if (ext4_es_is_written(&es) || ext4_es_is_unwritten(&es)) {
530				map->m_pblk = ext4_es_pblock(&es) +
531						map->m_lblk - es.es_lblk;
532				map->m_flags |= ext4_es_is_written(&es) ?
533						EXT4_MAP_MAPPED : EXT4_MAP_UNWRITTEN;
534				retval = es.es_len - (map->m_lblk - es.es_lblk);
535				if (retval > map->m_len)
536					retval = map->m_len;
537				map->m_len = retval;
538			} else if (ext4_es_is_delayed(&es) || ext4_es_is_hole(&es)) {
539				retval = 0;
540			} else {
541				BUG_ON(1);
542			}
543	#ifdef ES_AGGRESSIVE_TEST
544			ext4_map_blocks_es_recheck(handle, inode, map,
545						   &orig_map, flags);
546	#endif
547			goto found;
548		}
549	
550		/*
551		 * Try to see if we can get the block without requesting a new
552		 * file system block.
553		 */
554		if (!(flags & EXT4_GET_BLOCKS_NO_LOCK))
555			down_read((&EXT4_I(inode)->i_data_sem));
556		if (ext4_test_inode_flag(inode, EXT4_INODE_EXTENTS)) {
557			retval = ext4_ext_map_blocks(handle, inode, map, flags &
558						     EXT4_GET_BLOCKS_KEEP_SIZE);
559		} else {
560			retval = ext4_ind_map_blocks(handle, inode, map, flags &
561						     EXT4_GET_BLOCKS_KEEP_SIZE);
562		}
563		if (retval > 0) {
564			int ret;
565			unsigned int status;
566	
567			if (unlikely(retval != map->m_len)) {
568				ext4_warning(inode->i_sb,
569					     "ES len assertion failed for inode "
570					     "%lu: retval %d != map->m_len %d",
571					     inode->i_ino, retval, map->m_len);
572				WARN_ON(1);
573			}
574	
575			status = map->m_flags & EXT4_MAP_UNWRITTEN ?
576					EXTENT_STATUS_UNWRITTEN : EXTENT_STATUS_WRITTEN;
577			if (!(flags & EXT4_GET_BLOCKS_DELALLOC_RESERVE) &&
578			    !(status & EXTENT_STATUS_WRITTEN) &&
579			    ext4_find_delalloc_range(inode, map->m_lblk,
580						     map->m_lblk + map->m_len - 1))
581				status |= EXTENT_STATUS_DELAYED;
582			ret = ext4_es_insert_extent(inode, map->m_lblk,
583						    map->m_len, map->m_pblk, status);
584			if (ret < 0)
585				retval = ret;
586		}
587		if (!(flags & EXT4_GET_BLOCKS_NO_LOCK))
588			up_read((&EXT4_I(inode)->i_data_sem));
589	
590	found:
591		if (retval > 0 && map->m_flags & EXT4_MAP_MAPPED) {
592			int ret = check_block_validity(inode, map);
593			if (ret != 0)
594				return ret;
595		}
596	
597		/* If it is only a block(s) look up */
598		if ((flags & EXT4_GET_BLOCKS_CREATE) == 0)
599			return retval;
600	
601		/*
602		 * Returns if the blocks have already allocated
603		 *
604		 * Note that if blocks have been preallocated
605		 * ext4_ext_get_block() returns the create = 0
606		 * with buffer head unmapped.
607		 */
608		if (retval > 0 && map->m_flags & EXT4_MAP_MAPPED)
609			return retval;
610	
611		/*
612		 * Here we clear m_flags because after allocating an new extent,
613		 * it will be set again.
614		 */
615		map->m_flags &= ~EXT4_MAP_FLAGS;
616	
617		/*
618		 * New blocks allocate and/or writing to uninitialized extent
619		 * will possibly result in updating i_data, so we take
620		 * the write lock of i_data_sem, and call get_blocks()
621		 * with create == 1 flag.
622		 */
623		down_write((&EXT4_I(inode)->i_data_sem));
624	
625		/*
626		 * if the caller is from delayed allocation writeout path
627		 * we have already reserved fs blocks for allocation
628		 * let the underlying get_block() function know to
629		 * avoid double accounting
630		 */
631		if (flags & EXT4_GET_BLOCKS_DELALLOC_RESERVE)
632			ext4_set_inode_state(inode, EXT4_STATE_DELALLOC_RESERVED);
633		/*
634		 * We need to check for EXT4 here because migrate
635		 * could have changed the inode type in between
636		 */
637		if (ext4_test_inode_flag(inode, EXT4_INODE_EXTENTS)) {
638			retval = ext4_ext_map_blocks(handle, inode, map, flags);
639		} else {
640			retval = ext4_ind_map_blocks(handle, inode, map, flags);
641	
642			if (retval > 0 && map->m_flags & EXT4_MAP_NEW) {
643				/*
644				 * We allocated new blocks which will result in
645				 * i_data's format changing.  Force the migrate
646				 * to fail by clearing migrate flags
647				 */
648				ext4_clear_inode_state(inode, EXT4_STATE_EXT_MIGRATE);
649			}
650	
651			/*
652			 * Update reserved blocks/metadata blocks after successful
653			 * block allocation which had been deferred till now. We don't
654			 * support fallocate for non extent files. So we can update
655			 * reserve space here.
656			 */
657			if ((retval > 0) &&
658				(flags & EXT4_GET_BLOCKS_DELALLOC_RESERVE))
659				ext4_da_update_reserve_space(inode, retval, 1);
660		}
661		if (flags & EXT4_GET_BLOCKS_DELALLOC_RESERVE)
662			ext4_clear_inode_state(inode, EXT4_STATE_DELALLOC_RESERVED);
663	
664		if (retval > 0) {
665			int ret;
666			unsigned int status;
667	
668			if (unlikely(retval != map->m_len)) {
669				ext4_warning(inode->i_sb,
670					     "ES len assertion failed for inode "
671					     "%lu: retval %d != map->m_len %d",
672					     inode->i_ino, retval, map->m_len);
673				WARN_ON(1);
674			}
675	
676			/*
677			 * If the extent has been zeroed out, we don't need to update
678			 * extent status tree.
679			 */
680			if ((flags & EXT4_GET_BLOCKS_PRE_IO) &&
681			    ext4_es_lookup_extent(inode, map->m_lblk, &es)) {
682				if (ext4_es_is_written(&es))
683					goto has_zeroout;
684			}
685			status = map->m_flags & EXT4_MAP_UNWRITTEN ?
686					EXTENT_STATUS_UNWRITTEN : EXTENT_STATUS_WRITTEN;
687			if (!(flags & EXT4_GET_BLOCKS_DELALLOC_RESERVE) &&
688			    !(status & EXTENT_STATUS_WRITTEN) &&
689			    ext4_find_delalloc_range(inode, map->m_lblk,
690						     map->m_lblk + map->m_len - 1))
691				status |= EXTENT_STATUS_DELAYED;
692			ret = ext4_es_insert_extent(inode, map->m_lblk, map->m_len,
693						    map->m_pblk, status);
694			if (ret < 0)
695				retval = ret;
696		}
697	
698	has_zeroout:
699		up_write((&EXT4_I(inode)->i_data_sem));
700		if (retval > 0 && map->m_flags & EXT4_MAP_MAPPED) {
701			int ret = check_block_validity(inode, map);
702			if (ret != 0)
703				return ret;
704		}
705		return retval;
706	}
