712				   struct buffer_head *bh, int flags)
713	{
714		handle_t *handle = ext4_journal_current_handle();
715		struct ext4_map_blocks map;
716		int ret = 0, started = 0;
717		int dio_credits;
718	
719		if (ext4_has_inline_data(inode))
720			return -ERANGE;

